import { Component, OnInit } from '@angular/core';
import { FormControl, FormGroup, Validators } from '@angular/forms';
import { ActivatedRoute, Router } from '@angular/router';
import { NavController } from '@ionic/angular';
import { AlertService } from 'src/app/services/alert.service';
import { UserSessionService } from 'src/app/services/usersession.service';
import * as _ from 'lodash';
import { EmisService } from 'src/app/services/emis/emis.service';

@Component({
  selector: 'app-volunteer-search',
  templateUrl: './volunteer-search.page.html',
  styleUrls: ['./volunteer-search.page.scss'],
})
export class VolunteerSearchPage implements OnInit {
  [x: string]: any;
  volInfo: any;
  form: FormGroup;
  searchTxt: string;
  searchOption: string = "id";
  showList: boolean;
  userType: Number;
  id: Number;
  smcstatusList: any = [];
  constructor(private route: ActivatedRoute, private navCtrl: NavController, 
    private router: Router, private userSessionService: UserSessionService, private emisService: EmisService,
    private alertService: AlertService) {
  }

  ngOnInit() {
  }

  ionViewDidEnter() {
    debugger
    this.showList = false;
    this.routeData = this.route.snapshot;
    this.paramsVolunteerId = this.routeData.params.volunId;
    if(this.paramsVolunteerId) {
      this.searchTxt = this.paramsVolunteerId;
      this.emisService.searchVolunteerById(this.searchTxt).subscribe((res) => {
        if (res && res.dataStatus) {
          this.noData= false;
          this.volInfo = res.result[0];
          this.showList = true;
        } else {
          this.alertService.error(res.message);
          this.noData= true;
        }
      });
      this.emisService.searchVolunteerByPhone(this.searchTxt).subscribe((res) => {
        if (res && res.dataStatus) {
          this.noData= false;
          this.volInfo = res.result[0];
          this.showList = true;
        } else {
          this.alertService.error(res.message);
          this.noData= true;
        }
      });
    } else {
      this.searchTxt = "";
    }
  }

  doSearch() {
    if (this.searchOption == 'phone') {
      if (this.searchTxt && this.searchTxt.length == 10) {
        this.getVolunteerInfoServer();
      }
      else {
        this.alertService.error("Invalid phone number")
      }
    }
    else if (this.searchOption == 'id' && this.searchTxt) {
      this.getVolunteerInfoServer();
    }
  }

  getVolunteerInfoServer() {
    debugger
    if (this.searchOption == 'id') {
      this.emisService.searchVolunteerById(this.searchTxt).subscribe((res) => {
        if (res && res.dataStatus) {
          this.noData= false;
          this.volInfo = res.result[0];
          this.showList = true;
        }
        else if (res.message == "No Data Found") {
          this.noData= true;
          // this.alertService.error("This id or phone number is not available / volunteer discontinued")
          this.alertService.error(res.message);
        }else{
          this.noData= true;
          this.alertService.error(res.message);
        }
      });
    }
    else {
      this.emisService.searchVolunteerByPhone(this.searchTxt).subscribe((res) => {
        if (res && res.dataStatus) {
          this.noData= false;
          this.volInfo = res.result[0];
          this.showList = true;
        }
        else if (res.message == "No Data Found") {
          this.noData= true;
          this.alertService.error(res.message);
          // this.alertService.error("This id or phone number is not available / volunteer discontinued")
        }else{
          this.noData= true;
          this.alertService.error(res.message);
        }
      });

    }
  }

  startInspection() {
    this.router.navigate(['/tabs/volunteer-inspection'],{ queryParams: 
      { searchTxt : this.searchTxt, 
        volunteerId : this.volInfo.VolunteerId,
        VolEmisUsrName:this.volInfo.PhoneNo
      }});
    //  this.router.navigate(['/tabs/teacher/volunteer-inspection', { details: "volunteer", data: JSON.stringify(this.volInfo) }])
    // this.router.navigate(['/tabs/teacher/volunteer-inspection', { searchTxt : this.searchTxt,volunteerId : this.volInfo.VolunteerId,details: "volunteer", data: JSON.stringify(this.volInfo) }])
    // this.navCtrl.navigateForward(['/tabs/volunteer-inspection2'],{ queryParams: { searchTxt : this.searchTxt, volunteerId : this.volInfo.VolunteerId,VolEmisUsrName:this.volInfo.PhoneNo}});
  }

  onChange(event) {
    this.searchOption = event.detail.value;
  }
  goToBack() {
    // this.navCtrl.back();
    // this.router.navigate(['tabs/dashboard']);
    this.router.navigate(['tabs/itk-center-dashboard']); 
  }
}
